# Databricks notebook source
# MAGIC %md
# MAGIC # 07 · AI Functions: create loan intelligence with SQL
# MAGIC
# MAGIC > Input data is **synthetic** (it stands in for servicing-platform exports). The AI output is **real**:
# MAGIC > every summary below is generated by Claude through Databricks **AI Functions**.
# MAGIC
# MAGIC The rules engine (notebook 04) already computed *facts* for every loan: condition, days overdue, score
# MAGIC drivers, and the ranked queue. Here we turn those facts into plain-language intelligence **with one SQL
# MAGIC function: `ai_query`**. No pipelines to build, no model to host, governed by Unity Catalog, on serverless.
# MAGIC
# MAGIC | Output table | What it holds |
# MAGIC |---|---|
# MAGIC | `gold_ai_loan_insights` | One-sentence AI summary for each CRITICAL / HIGH loan |
# MAGIC | `gold_ai_portfolio_briefing` | A short AI morning briefing for servicing managers |

# COMMAND ----------

dbutils.widgets.text("catalog", "main", "Catalog")
dbutils.widgets.text("schema", "loan_servicing_intelligence", "Schema")
spark.sql(f"USE CATALOG `{dbutils.widgets.get('catalog')}`")
spark.sql(f"USE SCHEMA `{dbutils.widgets.get('schema')}`")

# COMMAND ----------

# MAGIC %md
# MAGIC ## 1. The facts the rules engine produced (Gold)

# COMMAND ----------

# MAGIC %sql
# MAGIC SELECT queue_rank, priority, loan_id, primary_condition, attention_score, top_drivers
# MAGIC FROM gold_loan_state
# MAGIC WHERE is_active
# MAGIC ORDER BY queue_rank
# MAGIC LIMIT 10

# COMMAND ----------

# MAGIC %md
# MAGIC ## 2. Ask the model to summarize each high-priority loan - in SQL
# MAGIC `ai_query(endpoint, prompt)` calls a Foundation Model API endpoint for every row, in parallel.

# COMMAND ----------

# MAGIC %sql
# MAGIC CREATE OR REPLACE TABLE gold_ai_loan_insights
# MAGIC COMMENT 'AI Functions (ai_query) loan summaries - SYNTHETIC DEMONSTRATION DATA' AS
# MAGIC SELECT
# MAGIC   loan_id,
# MAGIC   priority,
# MAGIC   primary_condition,
# MAGIC   attention_score,
# MAGIC   ai_query(
# MAGIC     'databricks-claude-sonnet-4-5',
# MAGIC     CONCAT(
# MAGIC       'You summarize SYNTHETIC loan-servicing data for a servicing specialist. In one sentence of at most ',
# MAGIC       '30 words, state why this loan needs attention and which servicing follow-up to check first. ',
# MAGIC       'Use only these facts. No legal or financial advice. Facts: ',
# MAGIC       to_json(transform(conditions, c -> c.detail)), ' | Score drivers: ', top_drivers,
# MAGIC       ' | Milestone: ', coalesce(current_milestone, 'none'), ' | Allowed actions: ', array_join(allowed_actions, ', '))
# MAGIC   ) AS ai_summary,
# MAGIC   'databricks-claude-sonnet-4-5' AS model_endpoint,
# MAGIC   current_timestamp() AS generated_at
# MAGIC FROM gold_loan_state
# MAGIC WHERE priority IN ('CRITICAL', 'HIGH')
# MAGIC ORDER BY queue_rank
# MAGIC LIMIT 25

# COMMAND ----------

# MAGIC %sql
# MAGIC SELECT loan_id, priority, attention_score, ai_summary
# MAGIC FROM gold_ai_loan_insights
# MAGIC ORDER BY attention_score DESC

# COMMAND ----------

